/**
 * 대학 학과별 취업률 (교육부·한국교육개발원 고등교육기관 졸업자 취업통계, 건강보험 DB 연계).
 *
 * 제공받은 파일 기준: 경기도 소재 대학 38곳, 2022~2024년 졸업자,
 * 학과(전공) 단위 3,232줄. 화면에서 다루기 쉽게 세 단위로 미리 합쳐 두었다.
 *
 * 취업률은 통계 정의 그대로다:
 *   취업자(B) ÷ [졸업자(A) − (진학 C + 입대 D + 취업불가 E + 외국인유학생 F + 건보 제외 G)]
 * 취업자에는 건강보험 직장가입자뿐 아니라 해외취업·영농·창작·1인창업·프리랜서가 든다.
 *
 * 학과 이름은 "전공/학과/학부" 꼬리를 떼고 학교를 넘어 묶었다. 같은 이름이라도 학교마다
 * 다른 과일 수 있으니 "이 이름의 과들이 대체로 어떻다" 정도로 읽어야 한다. 3년 합계
 * 졸업자 20명 미만인 이름은 뺐다 — 한두 명으로 100%·0%가 나오는 것은 통계가 아니다.
 */

export type YearStat = {
  grads: number;
  employed: number;
  /** 취업률 분모 (졸업자에서 진학·입대 등을 뺀 수) */
  den: number;
  rate: number | null;
};

export type OverallStat = YearStat & {
  rateM: number | null;
  rateF: number | null;
  free: number;
  solo: number;
  further: number;
  abroad: number;
};

export const MAJOR_YEARS = ["2022", "2023", "2024"];
