/** 졸업자가 어느 정도 있는 학과만 순위에 올린다. 분모가 작으면 한 명이 10%다. */
export function rankedMajors(min = 30) {
  return MAJORS.filter((m) => m.y[LATEST].den >= min && m.y[LATEST].rate !== null)
    .sort((a, b) => (b.y[LATEST].rate ?? 0) - (a.y[LATEST].rate ?? 0));
}

export function findMajors(q: string) {
  const s = q.trim().toLowerCase();
  if (!s) return MAJORS;
  return MAJORS.filter((m) => m.name.toLowerCase().includes(s));
}
